import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers (clinical/stratum features)
    clinical_features = [fid for fid, t in zip(feats.ids, feats.types) if t == 'clinical']

    if not clinical_features:
        # No clinical features, use all features
        drivers = ()
        columns = feats.ids[:MAX_DRIVERS]
        products = ()
        loadings = {}
        return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

    # Check if any clinical feature shows strong association with outcome
    best_clinical = None
    best_p = 1.0

    for fid in clinical_features:
        col_idx = feats.column(fid)
        x = feats.x[:, col_idx].reshape(-1, 1)
        clf = LogisticRegression(fit_intercept=True, solver='liblinear')
        clf.fit(x, feats.y)
        p_val = 2 * (1 - stats.norm.cdf(np.abs(clf.coef_[0][0])))

        if p_val < best_p:
            best_p = p_val
            best_clinical = fid

    # If no strong association, no mechanism
    if best_p > 0.05:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use clinical feature as driver
    drivers = (best_clinical,)

    # Remove correlated features to avoid multicollinearity
    feature_corr = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                feature_corr[(fid1, fid2)] = corr

    # Build list of candidate features excluding near-duplicates
    candidates = []
    used = set()

    for fid in feats.ids:
        if fid in used:
            continue

        # Add this feature
        candidates.append(fid)
        used.add(fid)

        # Remove correlated features
        for fid1, fid2 in feature_corr:
            if fid1 == fid and fid2 not in used:
                used.add(fid2)
            elif fid2 == fid and fid1 not in used:
                used.add(fid1)

    # Select top features based on t-test or other statistics
    columns = []
    for fid in candidates[:MAX_DRIVERS]:
        col_idx = feats.column(fid)
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])
        if p_val < 0.05 or abs(t_stat) > 1.5:
            columns.append(fid)

    # Create interaction terms for top two features
    products = ()
    if len(columns) >= 2:
        products = ((columns[0], columns[1]),)

    # Weighted score using top feature
    loadings = {}
    if columns:
        loadings[columns[0]] = 1.0

    return Design(drivers=drivers, columns=tuple(columns), products=products, loadings=loadings)

